import json
p='country_unique.json'
raw=open(p,encoding='utf8',newline='').read()
d=json.loads(raw)
t=d['tobacco']
t['bahrain']={"h":"What Bahrain Customs says about tobacco, e-cigarettes and nicotine pouches","p":["Bahrain Customs Affairs, on its page \"Duty Free Allowances\" (read from an archived copy on 24 November 2026), exempts personal effects and gifts carried by travellers if they are not commercial and worth no more than BD 300. For tobacco it lists 400 regular or electronically heated cigarettes, or the equivalent of 250 g of tobacco, or 400 nicotine pouches; 50 cigars; and a quarter of a kilo of pipe tobacco.","The same list allows ten electronic cigarettes, one electronic heating device, one electronic hookah device and 60 ml of liquid for electronic hookah filling, plus 3 litres of alcoholic beverages and 12 cans of beer. Tobacco and alcohol must be in the possession of someone aged 18 or over. The goods must not be commercial, the traveller must not be a frequent flyer bringing goods in regularly, and aircrew follow a separate mechanism. Customs may keep dutiable goods for up to three months at the traveller's request."],"src":"Source read: Bahrain Customs Affairs, Duty Free Allowances (customs.gov.bh), read from an archived copy on 24 November 2026."}
t['mauritius']={"h":"What the Mauritius Revenue Authority says about tobacco and alcohol","p":["The Mauritius Revenue Authority (MRA) page \"Allowances\", with rules in force from 1 September 2025, says a passenger aged 18 or over may bring 250 grams of tobacco, cigarettes and cigars included, and must choose only one of three combinations with it: option A adds 1 litre of spirits and 2 litres of wine, ale or beer; option B adds 2 litres of spirits; option C adds 4 litres of wine, ale or beer.","Duty, excise duty and VAT are payable on any quantity above the allowance. Passengers arriving from Rodrigues have their own values and buy their duty-free goods in a shop at the airport or port on the island of departure. The page limits other accompanied goods by value, Rs 15,000 for foreign passengers on international flights, and these must pass through customs arrival processes."],"src":"Source read: Mauritius Revenue Authority, Allowances (mra.mu), read from an archived copy on 24 November 2026.","link":["https://www.mra.mu/customs1/travellers/allowances","Mauritius Revenue Authority: Allowances"]}
open(p,'w',encoding='utf8',newline='').write(json.dumps(d,ensure_ascii=False,separators=(',',':'))+('\n' if raw.endswith('\n') else ''))
